 svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="800" height="450" viewBox="0 0 800 450"><rect width="800" height="450" fill="{colors[i%5]}"/><circle cx="620" cy="100" r="65" fill="#f3e3bd"/><path d="M0 340L210 140L420 330L570 210L800 390V450H0Z" fill="#233f48"/><path d="M0 400L280 290L550 410L800 330V450H0Z" fill="#172b32"/></svg>'
