EVENTS=['Page Viewed','Sign Up Started','Sign Up Completed','Onboarding Completed','Search Performed','Item Viewed','Item Added','Checkout Started','Purchase Completed','Invite Sent','Feature Used','Session Started','Settings Updated','Report Created','Export Completed','Subscription Started','Trial Started','Trial Converted','Notification Opened','Help Viewed']
def generate_data(page,sample_index=0,assets_dir=None):
 if page not in STATES:raise ValueError(page)
 people=[{'name':NAMES[i%12],'email':NAMES[i%12].lower().replace(' ','.')+'@example.test','avatar':avatar(i)} for i in range(12)]
 rows=[{'name':e,'owner':people[i%12]['name'],'users':28400-i*1140,'events':126000-i*4310,'type':['Product','Acquisition','Engagement','Revenue'][i%4],'status':'Live' if i%4 else 'Needs review','date':f'2026-10-{i+1:02d}','id':f'demo-user-{1000+i}','country':['South Korea','United States','United Kingdom','Japan'][i%4],'platform':['Web','iOS','Android'][i%3],'duration':f'{2+i%8}:{12+i:02d}'} for i,e in enumerate(EVENTS)]
 return {'page':page,'state':STATES[page][0],'popup_visible':False,'popup_mode':None,'keyboard_visible':False,'people':people,'rows':rows,'sample_index':sample_index,'query':'purchase','points':[round(35+i*1.5+14*math.sin((i+sample_index)/2),1) for i in range(28)]}
def apply_state(base,state):
 if state not in STATES[base['page']]:raise ValueError(state)
 d=copy.deepcopy(base);d.update(state=state,popup_visible=state in MODALS,popup_mode='modal' if state in MODALS else PANELS.get(state))
 if state=='empty':d['rows']=[]
 if state=='searching':d['rows']=[r for r in d['rows'] if 'Purchase' in r['name']]
 return d
